        (1, "जब बस अचानक मुड़ती है, तो उसमें बैठे यात्री बाहर की ओर झुक जाते हैं, इसका कारण क्या है?", ["गुरुत्वाकर्षण", "दिशा का जड़त्व (Inertia of Direction)", "घर्षण बल", "अभिकेंद्रीय बल"], "B", "न्यूटन के प्रथम नियम (जड़त्व नियम) के अनुसार वस्तु अपनी दिशा में परिवर्तन का विरोध करती है।", "NMMS Bihar 2023"),
        (2, "रॉकेट का अंतरिक्ष में ऊपर जाना न्यूटन के किस गति नियम पर आधारित है?", ["प्रथम नियम", "द्वितीय नियम", "तृतीय नियम (क्रिया-प्रतिक्रिया)", "गुरुत्वाकर्षण नियम"], "C", "रॉकेट से गैसें तीव्र वेग से पीछे निकलती हैं (क्रिया) और रॉकेट आगे बढ़ता है (प्रतिक्रिया)।", "NMMS UP 2022"),
        (3, "क्रिकेट खिलाड़ी गेंद को कैच करते समय अपने हाथों को पीछे क्यों खींचता है?", ["गेंद को देखने के लिए", "संवेग परिवर्तन का समय बढ़ाकर बल कम करने हेतु", "मजबूत पकड़ हेतु", "नियम के कारण"], "B", "समय (t) बढ़ने से बल (F = Δp/t) कम हो जाता है, जिससे हाथों पर चोट नहीं लगती।", "NMMS MP 2023"),
        (4, "ऊर्जा संरक्षण का नियम (Law of Conservation of Energy) क्या कहता है?", ["ऊर्जा पैदा की जा सकती है", "ऊर्जा न उत्पन्न की जा सकती है न नष्ट, केवल रूपांतरित होती है", "ऊर्जा हमेशा नष्ट होती है", "ऊर्जा घटती है"], "B", "ब्रह्मांड की कुल ऊर्जा नियत रहती है, इसे केवल एक रूप से दूसरे रूप में बदला जा सकता है।", "NMMS Rajasthan 2022"),
        (5, "बहते हुए पानी, उड़ते हवाई जहाज और दौड़ते बच्चे में कौन-सी ऊर्जा होती है?", ["स्थितिज ऊर्जा", "गतिज ऊर्जा (Kinetic Energy)", "रासायनिक ऊर्जा", "विद्युत ऊर्जा"], "B", "किसी वस्तु में उसकी गति के कारण निहित ऊर्जा को गतिज ऊर्जा कहते हैं (K = ½ mv²)।", "NMMS Haryana 2023"),
        (6, "बांध में रोके गए पानी या खींचे गए धनुष की डोरी में कौन-सी ऊर्जा संचित होती है?", ["गतिज ऊर्जा", "स्थितिज ऊर्जा (Potential Energy)", "ध्वनि ऊर्जा", "ऊष्मीय ऊर्जा"], "B", "वस्तु की स्थिति या विन्यास में परिवर्तन के कारण संचित ऊर्जा स्थितिज ऊर्जा (U = mgh) कहलाती है।", "NMMS Delhi 2022"),
        (7, "ध्वनि की गति वायु में 0°C पर लगभग कितनी होती है?", ["332 m/s (लगभग)", "1500 m/s", "3 × 10⁸ m/s", "100 m/s"], "A", "सामान्य शुष्क वायु में 0°C पर ध्वनि का वेग 332 मीटर प्रति सेकंड होता है।", "NMMS Bihar 2022"),
        (8, "प्रतिध्वनि (Echo) सुनने के लिए श्रोता और परावर्तक सतह के बीच न्यूनतम दूरी कितनी होनी चाहिए?", ["5 मीटर", "11 मीटर", "17.2 मीटर (लगभग 17 मीटर)", "25 मीटर"], "C", "मानव कान पर ध्वनि का प्रभाव 0.1 सेकंड रहता है, अतः 344 × 0.1 / 2 ≈ 17.2 मीटर दूरी जरूरी है।", "NMMS UP 2023"),
        (9, "चमगादड़ रात के अंधेरे में उड़ते समय किस तरंग का उपयोग कर शिकार पकड़ते हैं?", ["श्रव्य तरंगें", "पराश्रव्य तरंगें (Ultrasound)", "अवश्रव्य तरंगें", "रेडियो तरंगें"], "B", "चमगादड़ 20,000 Hz से अधिक आवृत्ति की पराश्रव्य तरंगें छोड़कर अवरोधों का पता लगाते हैं।", "NMMS MP 2022"),
        (10, "गाड़ियों के पहियों में खांचे (Treads) क्यों बनाए जाते हैं?", ["सुंदरता के लिए", "सड़क के साथ घर्षण बढ़ाने हेतु", "घर्षण घटाने के लिए", "वजन कम करने के लिए"], "B", "पहियों में खांचे बनाने से सड़क पर मजबूत पकड़ बनती है और फिसलने का खतरा नहीं रहता।", "NMMS Rajasthan 2021"),
        (11, "कैरोम बोर्ड पर बारीक पाउडर छिड़कने से घर्षण पर क्या प्रभाव पड़ता है?", ["घर्षण बढ़ जाता है", "घर्षण कम हो जाता है (Smooth)", "कोई प्रभाव नहीं पड़ता", "स्ट्राइकर भारी होता है"], "B", "पाउडर छिड़कने से सतह चिकनी हो जाती है और घर्षण बल घट जाता है जिससे गोटियां फिसलती हैं।", "NMMS All India 2022"),
        (12, "मशीनों में घर्षण कम करने के लिए किन पदार्थों का उपयोग किया जाता है?", ["पानी", "स्नेहक / लुब्रिकेंट (तेल, ग्रीस, ग्रेफाइट)", "रेत", "एसिड"], "B", "ग्रीस और तेल मशीन के पुर्जों के बीच पतली परत बनाकर संपर्क व घर्षण को न्यूनतम करते हैं।", "NMMS Gujarat 2023"),
        (13, "पेंसिल तराशने वाले शार्पनर में कौन-सा दर्पण लगा होता है?", ["उत्तल दर्पण", "अवतल दर्पण", "कोई दर्पण नहीं (ब्लेड होती है)", "समतल दर्पण"], "C", "शार्पनर में कोई दर्पण नहीं होता, उसमें केवल तेज धार वाली स्टील की ब्लेड होती है।", "NMMS Bihar 2021"),
        (14, "उत्तल दर्पण द्वारा बना प्रतिबिंब हमेशा कैसा होता है?", ["वास्तविक और उल्टा", "आभासी, सीधा और वस्तु से छोटा", "वास्तविक और बड़ा", "समतल"], "B", "उत्तल दर्पण सदैव आभासी, सीधा और वस्तु से छोटा प्रतिबिंब ही बनाता है।", "NMMS UP 2021"),
        (15, "लेंस की क्षमता (Power of Lens) का अंतरराष्ट्रीय मात्रक क्या है?", ["मीटर", "डायोप्टर (Dioptre - D)", "सेंटीमीटर", "हर्ट्ज़"], "B", "लेंस की क्षमता P = 1/f (मीटर में), इसका SI मात्रक डायोप्टर (D) होता है।", "NMMS MP 2023"),
        (16, "तत्वों की आधुनिक आवर्त सारणी (Modern Periodic Table) किस वैज्ञानिक ने बनाई?", ["मेंडेलीव", "हेनरी मोजले (Henry Moseley)", "डाल्टन", "न्यूलैंड्स"], "B", "1913 में हेनरी मोजले ने तत्वों को उनके परमाणु क्रमांक (Atomic Number) के बढ़ते क्रम में सजाया।", "NMMS Rajasthan 2023"),
        (17, "मेंडेलीव की मूल आवर्त सारणी किस आधार पर व्यवस्थित थी?", ["परमाणु क्रमांक", "परमाणु भार (Atomic Mass)", "संयोजकता", "घनत्व"], "B", "मेंडेलीव की आवर्त सारणी तत्वों के परमाणु भारों के आवर्ती फलन पर आधारित थी।", "NMMS Delhi 2023"),
        (18, "आधुनिक आवर्त सारणी में कुल कितने आवर्त (Periods) और वर्ग (Groups) हैं?", ["7 आवर्त और 18 वर्ग", "8 आवर्त और 16 वर्ग", "9 आवर्त और 18 वर्ग", "7 आवर्त और 8 वर्ग"], "A", "आधुनिक आवर्त सारणी में 7 क्षैतिज पंक्तियां (आवर्त) और 18 ऊर्ध्वाधर स्तंभ (वर्ग) हैं।", "NMMS Bihar 2023"),
        (19, "आवर्त सारणी के किस वर्ग के तत्वों को 'अक्रिय गैसें' या नोबल गैसें कहा जाता है?", ["वर्ग 1", "वर्ग 17 (हैलोजन)", "वर्ग 18 (उत्कृष्ट गैसें)", "वर्ग 2"], "C", "वर्ग 18 में हीलियम, नियॉन, आर्गन, क्रिप्टन, जीनॉन और रेडॉन अक्रिय गैसें हैं।", "NMMS UP 2022"),
        (20, "विद्युत बल्बों में अक्रिय वातावरण बनाने हेतु कौन-सी गैस भरी जाती है?", ["ऑक्सीजन", "आर्गन (Argon) या नाइट्रोजन", "क्लोरीन", "हाइड्रोजन"], "B", "आर्गन एक अक्रिय गैस है जो तप्त टंगस्टन फिलामेंट को जलने या वाष्पीकृत होने से बचाती है।", "NMMS MP 2022"),
        (21, "हवाई जहाजों के टायरों में कौन-सी हल्की व अज्वलनशील गैस भरी जाती है?", ["हाइड्रोजन", "नाइट्रोजन (N₂)", "ऑक्सीजन", "मीथेन"], "B", "नाइट्रोजन गैस ठंडी रहती है, अज्वलनशील है और उच्च घर्षण में टायर को फटने से बचाती है।", "NMMS Haryana 2022"),
        (22, "मौसम का पूर्वानुमान लगाने वाले गुब्बारों में कौन-सी हल्की गैस भरी जाती है?", ["हाइड्रोजन", "हीलियम (Helium)", "नाइट्रोजन", "आर्गन"], "B", "हीलियम वायु से अत्यंत हल्की और अज्वलनशील गैस है, अतः गुब्बारों में सुरक्षित है।", "NMMS Rajasthan 2022"),
        (23, "गोताखोर गहरे समुद्र में सांस लेने हेतु ऑक्सीजन के साथ किस गैस का मिश्रण ले जाते हैं?", ["नाइट्रोजन", "हीलियम (Helium)", "कार्बन डाइऑक्साइड", "मीथेन"], "B", "हीलियम रक्त में कम घुलनशील होती है, जिससे गोताखोरों को 'बेंड्स' नामक दर्द नहीं होता।", "NMMS All India 2023"),
        (24, "शुद्ध सोना कितने कैरेट का होता है?", ["18 कैरेट", "22 कैरेट", "24 कैरेट (24 Carat)", "20 कैरेट"], "C", "24 कैरेट सोना 100% शुद्ध होता है, आभूषण बनाने हेतु इसमें तांबा मिलाकर 22 कैरेट बनाते हैं।", "NMMS Gujarat 2022"),
        (25, "18 कैरेट सोने में शुद्ध सोने का कितना प्रतिशत भाग होता है?", ["50%", "75% (75% शुद्ध सोना)", "90%", "85%"], "B", "18/24 × 100 = 75% शुद्ध सोना और 25% तांबा या चांदी मिलाया जाता है।", "NMMS Bihar 2022"),
        (26, "स्टेनलेस स्टील (Stainless Steel) में लोहे के साथ किन धातुओं को मिलाया जाता है?", ["तांबा व जस्ता", "क्रोमियम, निकेल और कार्बन", "सीसा व टिन", "एल्युमिनियम व जस्ता"], "B", "लोहे में क्रोमियम (18%) और निकेल मिलाने से उस पर कभी जंग नहीं लगता।", "NMMS UP 2023"),
        (27, "जर्मन सिल्वर (German Silver) मिश्र धातु में चांदी (Silver) का कितना प्रतिशत होता है?", ["50%", "20%", "0% (शून्य प्रतिशत)", "80%"], "C", "जर्मन सिल्वर तांबा (60%), जस्ता (20%) और निकेल (20%) की मिश्र धातु है; इसमें चांदी 0% होती है।", "NMMS MP 2023"),
        (28, "टांका / सोल्डर (Solder) तार किन दो धातुओं की मिश्र धातु है?", ["तांबा और जस्ता", "सीसा और टिन (Pb + Sn)", "लोहा और कार्बन", "सोना और तांबा"], "B", "सोल्डर तार सीसा (50%) और टिन (50%) की कम गलनांक वाली मिश्र धातु है जो तारों को जोड़ती है।", "NMMS Rajasthan 2021"),
        (29, "सड़कों पर पीली रोशनी देने वाले सोडियम लैंप में किस धातु की वाष्प होती है?", ["पारा", "सोडियम (Sodium)", "टंगस्टन", "तांबा"], "B", "सोडियम वाष्प लैंप तीखा पीला प्रकाश देते हैं जो कोहरे में भी साफ दिखाई देता है।", "NMMS Delhi 2023"),
        (30, "ट्यूबलाइट (Fluorescent Tube) में मुख्य रूप से कौन-सी गैस और वाष्प भरी होती है?", ["ऑक्सीजन व नाइट्रोजन", "आर्गन गैस और पारे की वाष्प (Hg Vapor)", "हीलियम व हाइड्रोजन", "क्लोरीन"], "B", "ट्यूबलाइट में कम दाब पर आर्गन गैस और पारे की वाष्प भरी जाती है।", "NMMS Bihar 2021"),
        (31, "शरीर के तापमान को नियंत्रित करने वाला मस्तिष्क का भाग कौन-सा है?", ["सेरेब्रम", "हाइपोथैलेमस (Hypothalamus)", "सेरेबेलम", "मेडुला"], "B", "मस्तिष्क का हाइपोथैलेमस भाग शरीर के तापमान, भूख, प्यास और भावनाओं को नियंत्रित करता है।", "NMMS UP 2021"),
        (32, "मानव मस्तिष्क का कौन-सा भाग शरीर का संतुलन और चलने-फिरने का समन्वय करता है?", ["हाइपोथैलेमस", "अनुमस्तिष्क / सेरेबेलम (Cerebellum)", "प्रमस्तिष्क", "मेरुरज्जु"], "B", "सेरेबेलम (छोटा दिमाग) पेशियों की गति और शारीरिक संतुलन को बनाए रखता है।", "NMMS MP 2022"),
        (33, "मानव मस्तिष्क का सबसे बड़ा और विकसित भाग कौन-सा है जो सोचने-समझने का केंद्र है?", ["प्रमस्तिष्क / सेरेब्रम (Cerebrum)", "सेरेबेलम", "मेडुला", "थैलेमस"], "A", "सेरेब्रम (प्रमस्तिष्क) बुद्धि, स्मृति, चेतना और तर्कशक्ति का मुख्य केंद्र है।", "NMMS Rajasthan 2023"),
        (34, "प्रतिवर्ती क्रियाओं (Reflex Actions) का नियंत्रण केंद्र कौन-सा है?", ["प्रमस्तिष्क", "मेरुरज्जु (Spinal Cord)", "अनुमस्तिष्क", "नेत्र"], "B", "हाथ का गर्म वस्तु से अचानक हटना जैसी त्वरित अनैच्छिक क्रियाओं को मेरुरज्जु नियंत्रित करता है।", "NMMS All India 2022"),
        (35, "मानव शरीर की सबसे लंबी तंत्रिका कोशिका को क्या कहते हैं?", ["नेफ्रॉन", "न्यूरॉन (Neuron)", "अस्थि कोशिका", "मायोसाइट"], "B", "न्यूरॉन तंत्रिका तंत्र की मूल संरचनात्मक एवं क्रियात्मक इकाई है।", "NMMS Gujarat 2023"),
        (36, "मानव शरीर में कुल कितने क्रेनियल तंत्रिकाएं (Cranial Nerves) पाई जाती हैं?", ["12 जोड़े (12 Pairs)", "31 जोड़े", "10 जोड़े", "24 जोड़े"], "A", "मस्तिष्क से 12 जोड़े कपाल तंत्रिकाएं तथा मेरुरज्जु से 31 जोड़े मेरु तंत्रिकाएं निकलती हैं।", "NMMS Bihar 2023"),
